import React from "react";
import { useLocation, useNavigate } from "react-router-dom";
import "./global.css";

export default function ProductPage() {
  const location = useLocation();
  const navigate = useNavigate();
  const product = location.state?.product;

  if (!product) {
    return (
      <div style={{ textAlign: "center", marginTop: "50px" }}>
        <h2>Product not found</h2>
        <button onClick={() => navigate("/")}>Go Back</button>
      </div>
    );
  }

  const sizes = ["S", "M", "L", "XL"];

  return (
    <div className="product-detail">
      <div className="product-image-section">
        <img src={product.image} alt={product.name} className="detail-img" />
      </div>

      <div className="product-detail-info">
        <h1>{product.name}</h1>
        <p className="detail-desc">
          This {product.name} is made from sustainable materials, combining
          comfort, style, and eco-conscious design. Perfect for everyday wear or
          special occasions, it brings together fashion and responsibility.
        </p>

        <p className="detail-price">₹{product.price}</p>

        <div className="sizes">
          <p><b>Available Sizes:</b></p>
          <div className="size-options">
            {sizes.map((s) => (
              <button key={s} className="size-btn">{s}</button>
            ))}
          </div>
        </div>

        <div className="product-actions">
          <button className="buy-btn">Buy Now</button>
          <button className="swap-btn">Swap Item</button>
        </div>
      </div>
    </div>
  );
}
